import { StyleSheet } from "@/lib/pdf-primitives";
import type { PdfcnTheme } from "@/types/pdf-themes";

/**
 * Creates all quote styles derived from the active theme.
 * @param t - The resolved PdfcnTheme instance.
 */
export const createQuoteStyles = (t: PdfcnTheme) => {
  const { heading, body } = t.typography;
  const { spacing, fontWeights, lineHeights, typography } = t.primitives;
  const c = t.colors;

  return StyleSheet.create({
    bar: {
      borderLeftWidth: 3,
      paddingLeft: spacing[4],
      paddingVertical: spacing[1],
    },
    centered: {
      alignItems: "center",
    },
    cite: {
      color: c.mutedForeground,
      fontFamily: body.fontFamily,
      fontSize: typography.xs,
      lineHeight: lineHeights.normal,
      marginTop: spacing[2],
    },
    container: {
      display: "flex",
      flexDirection: "column",
      marginBottom: t.spacing.componentGap,
    },
    mark: {
      fontFamily: heading.fontFamily,
      // Oversized opening quote; tight line height keeps it close to the text.
      fontSize: Math.round(typography["3xl"] * 1.5),
      fontWeight: fontWeights.bold,
      lineHeight: 1,
      marginBottom: -spacing[3],
    },
    text: {
      color: c.foreground,
      fontFamily: body.fontFamily,
      fontSize: typography.lg,
      fontStyle: "italic",
      lineHeight: lineHeights.normal,
    },
  });
};

import {
  mergePdfStyles,
  usePdfcnTheme,
  useSafeMemo,
} from "@/components/pdf/theme-provider";
import {
  Text as PDFText,
  View,
} from "@/lib/pdf-primitives";
import type { Style } from "@/lib/pdf-primitives";
import { resolveColor } from "@/lib/resolve-color";

import { createQuoteStyles } from "./quote.styles";
import type { QuoteProps } from "./quote.types";

export type { QuoteAlign, QuoteProps } from "./quote.types";

export const Quote = ({
  text,
  cite,
  align = "left",
  accentColor = "primary",
  style,
}: QuoteProps) => {
  const theme = usePdfcnTheme();
  const styles = useSafeMemo(() => createQuoteStyles(theme), [theme]);
  const accent = resolveColor(accentColor, theme.colors);
  const alignment: Style = { textAlign: align };
  const centered = align === "center";

  const containerStyles: Style[] = [
    styles.container,
    ...(centered
      ? [styles.centered]
      : [styles.bar, { borderLeftColor: accent }]),
  ];
  if (style) {
    containerStyles.push(...[style].flat());
  }

  return (
    <View wrap={false} style={mergePdfStyles(containerStyles)}>
      {centered && (
        <PDFText style={mergePdfStyles(styles.mark, { color: accent })}>
          “
        </PDFText>
      )}
      <PDFText style={mergePdfStyles(styles.text, alignment)}>{text}</PDFText>
      {cite && (
        <PDFText style={mergePdfStyles(styles.cite, alignment)}>
          {`— ${cite}`}
        </PDFText>
      )}
    </View>
  );
};

import type { PDFComponentProps } from "@/types/pdf-components";

/** Horizontal alignment for the quote block. */
export type QuoteAlign = "left" | "center";

/**
 * Pull quote with optional attribution, for testimonials, press citations and epigraphs.
 * Props - `text` | `cite` | `align` | `accentColor` | `style`
 * @see {@link QuoteProps}
 */
export interface QuoteProps extends Omit<PDFComponentProps, "children"> {
  text: string;
  /**
   * Attribution rendered below the quote as "— {cite}".
   */
  cite?: string;
  /**
   * `left` draws an accent bar beside the quote; `center` draws an oversized
   * quotation mark above it.
   * @default 'left'
   */
  align?: QuoteAlign;
  /**
   * Color of the accent bar or quotation mark. Accepts theme color keys or any CSS color.
   * @default 'primary'
   */
  accentColor?: string;
}
